/* ===== Einheit 3 ===== */
EH[3]={z:'Wie kommt man an die Leistung? Beratung, Auskunft, Antrag, Handlungsfähigkeit betreuter Menschen, Grundsätze des Verwaltungsverfahrens und der Verwaltungsakt samt Bekanntgabe und Fristberechnung.',
 ks:['Beratung ist ein Rechtsanspruch; Beratungsfehler können über den Herstellungsanspruch korrigiert werden.','Anträge sind formfrei und können bei jeder Gemeinde und jedem Sozialleistungsträger fristwahrend gestellt werden.','Die Betreuung beseitigt die Handlungsfähigkeit nicht; nur Einwilligungsvorbehalt oder Geschäftsunfähigkeit schränken sie ein.','Ein Verwaltungsakt ist auch dann wirksam, wenn er falsch ist; er muss rechtzeitig angefochten werden.','Fristen beginnen mit der Bekanntgabe, nicht mit dem Lesen.'],
 kq:[['Worin unterscheiden sich Beratung und Auskunft?','Beratung durch den zuständigen Träger über die eigenen Rechte und Pflichten (§ 14 SGB I); Auskunft durch die Auskunftsstellen über Zuständigkeiten und Sach- und Rechtsfragen (§ 15 SGB I).'],
 ['Ein betreuter Mensch stellt beim Rentenversicherungsträger einen Antrag auf Grundsicherung im Alter. Was geschieht?','Der Rentenversicherungsträger nimmt den Antrag entgegen und leitet ihn unverzüglich an den Sozialhilfeträger weiter; der Antrag gilt als am Eingangstag gestellt (§ 16 Abs. 1, 2 SGB I).'],
 ['Welche drei Voraussetzungen hat der sozialrechtliche Herstellungsanspruch?','Pflichtverletzung des Trägers (meist Beratungsfehler), dadurch verursachter Nachteil, Ausgleich durch zulässige Amtshandlung möglich.'],
 ['Ist eine Betreuerin verpflichtet, ein Antragsformular zu verwenden?','Nein. Formulare sollen benutzt werden (§ 60 Abs. 2 SGB I), der Antrag ist aber auch formlos wirksam.'],
 ['Ein Bescheid wird am Freitag, 27. November 2026, zur Post gegeben. Wann endet die Widerspruchsfrist?','Bekanntgabe am Dienstag, 1. Dezember 2026 (vierter Tag, § 37 Abs. 2 SGB X). Fristende nach Monatsberechnung wäre Freitag, 1. Januar 2027 – ein Feiertag; die Frist endet am Montag, 4. Januar 2027 (§ 64 Abs. 3 SGG).'],
 ['Wann kann ein betreuter Mensch keinen wirksamen Widerspruch einlegen?','Bei Geschäftsunfähigkeit oder wenn ein Einwilligungsvorbehalt den Bereich erfasst und keine Einwilligung vorliegt; ferner nach einer Ausschließlichkeitserklärung der Betreuerin oder des Betreuers.']]};

N('n_beratung','t_verfahren','Aufklärung, Beratung und Auskunft',{p:'§§ 13–15 SGB I',k:['SGB I|13','SGB I|14','SGB I|15'],m:[3],src:'SGBI',sum:'Dreistufenmodell der Information; Beratung ist ein Rechtsanspruch, bei Fehlern greift der Herstellungsanspruch.',
 b:`<div class="tw"><table><thead><tr><th>Stufe</th><th>Norm</th><th>Adressat</th><th>Inhalt</th></tr></thead><tbody>
<tr><td>Aufklärung</td><td>§ 13 SGB I</td><td>Allgemeinheit</td><td>Allgemeine Information über Rechte und Pflichten (Broschüren, Internet)</td></tr>
<tr><td>Beratung</td><td>§ 14 SGB I</td><td>Einzelne Person</td><td>Individuelle Beratung über eigene Rechte und Pflichten durch den zuständigen Träger</td></tr>
<tr><td>Auskunft</td><td>§ 15 SGB I</td><td>Einzelne Person</td><td>Benennung des zuständigen Trägers, Auskunft über Sach- und Rechtsfragen durch Landesstellen sowie Kranken- und Pflegekassen</td></tr></tbody></table></div>
<p><b>§ 14 SGB I:</b> Jeder hat Anspruch auf Beratung über seine Rechte und Pflichten nach dem SGB; zuständig sind die Leistungsträger, denen gegenüber die Rechte geltend zu machen oder die Pflichten zu erfüllen sind. Der Anspruch ist ein echter Rechtsanspruch; die Beratung muss <b>richtig, vollständig und verständlich</b> sein. Aus § 14 in Verbindung mit § 2 Abs. 2 und § 17 Abs. 1 SGB I leitet die Rechtsprechung eine Pflicht zur <b>Spontanberatung</b> ab: Drängt sich bei konkretem Anlass eine naheliegende Gestaltungsmöglichkeit auf, muss der Träger auch ungefragt hinweisen.</p>
<h4>Praxis für Betreuerinnen und Betreuer</h4>
<ul><li>Beratung verlangen, möglichst schriftlich dokumentiert.</li><li>Verständliche Form: § 17 Abs. 1 Nr. 4 und Abs. 2 SGB I verpflichten zu barrierefreier Kommunikation einschließlich Gebärdensprache.</li><li>Wichtige telefonische Auskünfte mit Datum, Uhrzeit, Gesprächspartner und Inhalt in der Betreuungsakte vermerken.</li></ul>`,
 f:'Beratung (zuständiger Träger, eigene Rechte) ≠ Auskunft (Zuständigkeit, Sach- und Rechtsfragen). Dokumentation von Auskünften.',
 q:['Was folgt aus der „Spontanberatung“?','Drängt sich bei einem konkreten Anlass eine naheliegende Gestaltungsmöglichkeit auf, muss der Träger auch ungefragt darauf hinweisen (§ 14 SGB I i. V. m. § 2 Abs. 2, § 17 Abs. 1 SGB I); Verletzung kann einen Herstellungsanspruch begründen.'],
 rel:['n_herstellung','n_antrag','n_gg3'],l:LK(['SGB I',13],['SGB I',14],['SGB I',15],['SGB I',17])});
N('n_herstellung','t_verfahren','Sozialrechtlicher Herstellungsanspruch',{p:'Richterrecht (BSG)',m:[3],src:'SGBI',sum:'Wer wegen eines Beratungsfehlers einen Nachteil erleidet, wird so gestellt, als hätte der Träger richtig gehandelt.',
 b:`<p>Der Herstellungsanspruch ist nicht ausdrücklich geregelt, sondern von der Rechtsprechung des Bundessozialgerichts entwickelt. <b>Drei Voraussetzungen:</b></p>
<ol><li>Pflichtverletzung eines Sozialleistungsträgers, typischerweise unterlassene oder fehlerhafte Beratung,</li><li>ein dadurch verursachter sozialrechtlicher Nachteil (z. B. verspäteter Antrag),</li><li>der Nachteil lässt sich durch eine zulässige Amtshandlung ausgleichen.</li></ol>
<p><b>Rechtsfolge:</b> Der Betroffene wird so gestellt, als hätte der Träger richtig gehandelt – z. B. durch Fiktion eines früheren Antrags. Der Anspruch hilft <b>nicht</b>, wenn tatsächliche Voraussetzungen fehlen, die nicht durch Verwaltungshandeln ersetzt werden können (etwa eine tatsächlich nicht ausgeübte Beschäftigung).</p>`,
 f:'Drei Voraussetzungen auswendig; Gegenbeispiel: fehlende tatsächliche Voraussetzungen.',
 q:['Wann hilft der Herstellungsanspruch nicht?','Wenn tatsächliche Voraussetzungen fehlen, die nicht durch eine zulässige Verwaltungshandlung ersetzt werden können, etwa eine tatsächlich nicht erzielte Beschäftigung.'],
 rel:['n_beratung','n_antrag','f3_1','f3_2'],l:[]});
N('n_antrag','t_verfahren','Der Antrag',{p:'§ 16 SGB I',k:['SGB I|16','SGB I|36a','SGB II|37','SGB XII|44','SGB XII|18','SGB VI|99','SGB XI|33'],m:[3],src:'SGBI',sum:'Formfrei, bei jedem Träger und jeder Gemeinde fristwahrend möglich; Bedeutung und Rückwirkung unterscheiden sich je Leistungsgesetz.',
 b:`<p><b>§ 16 Abs. 1 SGB I:</b> Anträge sind beim zuständigen Träger zu stellen, werden aber auch von allen anderen Leistungsträgern und allen Gemeinden entgegengenommen. <b>Abs. 2:</b> Anträge bei unzuständigen Stellen sind <b>unverzüglich weiterzuleiten</b>; ist die Leistung antragsabhängig, gilt der Antrag als zum Zeitpunkt des Eingangs bei einer dieser Stellen gestellt. <b>Abs. 3:</b> Die Träger müssen darauf hinwirken, dass klare und sachdienliche Anträge gestellt und unvollständige Angaben ergänzt werden.</p>
<p>Der Antrag ist eine einseitige, empfangsbedürftige öffentlich-rechtliche Willenserklärung und <b>formfrei</b>; es genügt, dass erkennbar eine Sozialleistung begehrt wird. Formulare dienen der Sachverhaltsaufklärung (§ 60 Abs. 2 SGB I), sind aber keine Wirksamkeitsvoraussetzung. Anträge werden nach dem <b>Meistbegünstigungsprinzip</b> ausgelegt.</p>
<h4>Bedeutung des Antrags je Leistungsbereich</h4>
<div class="tw"><table><thead><tr><th>Leistungsbereich</th><th>Bedeutung</th><th>Norm</th></tr></thead><tbody>
<tr><td>SGB II</td><td>konstitutiv; wirkt auf den Ersten des Monats zurück</td><td>§ 37 SGB II</td></tr>
<tr><td>SGB XII Grundsicherung im Alter/bei Erwerbsminderung</td><td>konstitutiv; Wirkung auf den Ersten des Antragsmonats</td><td>§ 44 SGB XII</td></tr>
<tr><td>SGB XII Hilfe zum Lebensunterhalt</td><td>kein Antrag nötig; Kenntnis des Trägers genügt</td><td>§ 18 SGB XII</td></tr>
<tr><td>Gesetzliche Rentenversicherung</td><td>Antrag; bei Antrag nach Ablauf des dritten Kalendermonats nach Erfüllung der Voraussetzungen beginnt die Rente erst mit dem Antragsmonat</td><td>§ 99 SGB VI</td></tr>
<tr><td>Pflegeversicherung</td><td>Antrag; Leistungen ab Antragstellung, frühestens ab Vorliegen der Voraussetzungen</td><td>§ 33 SGB XI</td></tr></tbody></table></div>
<p><b>§ 37 SGB II:</b> Leistungen werden auf Antrag erbracht; Leistungen nach § 24 Abs. 1 und 3 und für Bedarfe nach § 28 Abs. 5 sind gesondert zu beantragen; für Zeiten vor der Antragstellung wird nicht geleistet, der Antrag auf Lebensunterhalt wirkt aber auf den Monatsersten zurück.</p>
<h4>Elektronische Kommunikation</h4>
<p>Nach § 36a SGB I zulässig, soweit der Empfänger einen Zugang eröffnet. Für zum Abruf bereitgestellte Verwaltungsakte (Online-Postfach) verlangt § 37 Abs. 2a SGB X die <b>Einwilligung</b> des Beteiligten.</p>`,
 f:'Typische Frage: Antrag beim falschen Träger – verloren? Nein: weiterleiten, Eingangsdatum zählt (§ 16 Abs. 2 SGB I). Rückwirkung: SGB II/XII auf den Monatsersten.',
 q:['Ein Antrag auf Grundsicherung wird bei der Gemeinde eingeworfen und liegt dort wochenlang. Was gilt?','Gemeinden müssen Anträge entgegennehmen und unverzüglich an den zuständigen Träger weiterleiten; der Antrag gilt als zum Zeitpunkt des Eingangs bei der Gemeinde gestellt (§ 16 Abs. 1, 2 SGB I). Der Antrag wirkt im SGB II auf den Monatsersten zurück (§ 37 SGB II).'],
 rel:['n_traeger','n_herstellung','n_handlung','f3_1','n_zugang'],l:LK(['SGB I',16],['SGB II',37],['SGB XII',44],['SGB VI',99],['SGB XI',33])});
N('n_handlung','t_verfahren','Handlungsfähigkeit und Vertretung betreuter Menschen',{p:'§ 36 SGB I, § 11 SGB X',k:['SGB I|36','SGB X|11','SGB X|13','BGB|1823','BGB|1825'],m:[3],src:'SGBX',sum:'Betreuung ändert die Handlungsfähigkeit nicht; Einwilligungsvorbehalt oder Geschäftsunfähigkeit schränken sie ein.',
 b:`<p>Nach <b>§ 11 Abs. 1 Nr. 1 SGB X</b> sind geschäftsfähige natürliche Personen handlungsfähig; <b>§ 36 SGB I</b> erweitert das: Wer das 15. Lebensjahr vollendet hat, kann Anträge stellen und verfolgen sowie Leistungen entgegennehmen.</p>
<h4>Betreute Menschen</h4>
<ul><li>Die Bestellung ändert an der Geschäftsfähigkeit nichts. Betreute bleiben grundsätzlich handlungsfähig: eigene Anträge, Widerspruch, Entgegennahme von Bescheiden.</li><li>Bei <b>Einwilligungsvorbehalt</b> (§ 1825 BGB) für den Bereich ist der betreute Mensch nur handlungsfähig, soweit er nach bürgerlichem Recht ohne Einwilligung handeln kann (§ 11 Abs. 2 SGB X).</li><li>Bei <b>Geschäftsunfähigkeit</b> (§ 104 Nr. 2 BGB) fehlt die Handlungsfähigkeit; dann handelt allein die Betreuerin bzw. der Betreuer.</li></ul>
<p>Die Betreuerin vertritt im Aufgabenkreis gerichtlich und außergerichtlich (§ 1823 BGB); Maßstab sind die Wünsche des Betreuten (§ 1821 Abs. 2–4 BGB), Vertretungsmacht nur soweit erforderlich (§ 1821 Abs. 1 Satz 2 BGB).</p>
<p><b>Doppelzuständigkeit:</b> Betreuter und Betreuer können nebeneinander handeln, auch widersprechend. Für das Gerichtsverfahren kann der Betreuer erklären, das Verfahren ausschließlich zu führen (§ 53 Abs. 2 ZPO); über § 11 Abs. 3 SGB X gilt das für das Verwaltungsverfahren entsprechend.</p>
<h4>Betreuer, Bevollmächtigte, Beistände</h4>
<div class="tw"><table><thead><tr><th></th><th>Betreuer</th><th>Bevollmächtigter</th><th>Beistand</th></tr></thead><tbody><tr><td>Grundlage</td><td>Gerichtlicher Beschluss, § 1823 BGB</td><td>Vollmacht, § 13 SGB X</td><td>§ 13 Abs. 4 SGB X</td></tr><tr><td>Nachweis</td><td>Betreuerausweis (§ 290 FamFG)</td><td>Schriftliche Vollmacht auf Verlangen</td><td>kein Nachweis</td></tr><tr><td>Behörde wendet sich an ihn?</td><td>im Aufgabenkreis als gesetzliche Vertretung</td><td>Ja (§ 13 Abs. 3 SGB X), wenn nicht unverzüglich widersprochen</td><td>Nein; Vortrag gilt als vom Beteiligten vorgebracht</td></tr></tbody></table></div>
<div class="mark"><b>Entscheidungsbaum:</b> Geschäftsfähig? Nein (§ 104 Nr. 2 BGB) → nur Betreuer handelt. Ja → Einwilligungsvorbehalt im Bereich? Nein → beide handlungsfähig (Doppelzuständigkeit); Ja → Betreute nur mit Einwilligung handlungsfähig.</div>`,
 f:'Wer handelt im Verfahren? Entscheidungsbaum: Geschäftsfähigkeit → Einwilligungsvorbehalt → Doppelzuständigkeit.',
 q:['Verliert ein betreuter Mensch durch die Bestellung eines Betreuers die Möglichkeit, Widerspruch einzulegen?','Nein. Die Betreuung ändert die Handlungsfähigkeit nicht. Sie fehlt nur bei Geschäftsunfähigkeit (§ 104 Nr. 2 BGB) oder – ohne Einwilligung – bei einem Einwilligungsvorbehalt im betreffenden Bereich (§ 11 Abs. 2 SGB X).'],
 rel:['n_bekanntgabe','n_antrag','f3_4','n_wid'],l:LK(['SGB I',36],['SGB X',11],['SGB X',13])});
N('n_grundsaetze','t_verfahren','Grundsätze des Verwaltungsverfahrens',{p:'§§ 9, 20, 21, 24, 25 SGB X',k:['SGB X|9','SGB X|20','SGB X|21','SGB X|25'],m:[3],src:'SGBX',sum:'Nichtförmlichkeit, Untersuchungsgrundsatz, Beweismittel, Anhörung, Akteneinsicht und Sozialgeheimnis.',
 b:`<div class="tw"><table><thead><tr><th>Grundsatz</th><th>Norm</th><th>Inhalt</th></tr></thead><tbody>
<tr><td>Nichtförmlichkeit</td><td>§ 9 SGB X</td><td>einfach, zweckmäßig und zügig</td></tr>
<tr><td>Untersuchungsgrundsatz</td><td>§ 20 SGB X</td><td>Ermittlung von Amts wegen, auch günstige Umstände</td></tr>
<tr><td>Beweismittel</td><td>§ 21 SGB X</td><td>Auskünfte, Urkunden, Sachverständige, Augenschein</td></tr>
<tr><td>Anhörung</td><td>§ 24 SGB X</td><td>vor belastendem Verwaltungsakt Gelegenheit zur Äußerung</td></tr>
<tr><td>Akteneinsicht</td><td>§ 25 SGB X</td><td>soweit zur Geltendmachung rechtlicher Interessen erforderlich</td></tr>
<tr><td>Sozialgeheimnis</td><td>§ 35 SGB I, §§ 67 ff. SGB X</td><td>Schutz der Sozialdaten</td></tr></tbody></table></div>`,
 f:'Amtsermittlung ≠ Entlastung von Mitwirkung (siehe Einheit 9).',rel:['n_anhoerung','n_datenschutz','n_mitw'],l:LK(['SGB X',9],['SGB X',20],['SGB X',21],['SGB X',25])});
N('n_anhoerung','t_verfahren','Anhörung',{p:'§ 24 SGB X',k:['SGB X|24','SGB X|41'],m:[3],src:'SGBX',sum:'Vor jedem belastenden Verwaltungsakt ist Gelegenheit zur Äußerung zu geben – das Anhörungsschreiben nie unbeantwortet lassen.',
 b:`<p><b>§ 24 Abs. 1 SGB X:</b> Bevor ein Verwaltungsakt erlassen wird, der in Rechte eines Beteiligten eingreift, ist diesem Gelegenheit zu geben, sich zu den entscheidungserheblichen Tatsachen zu äußern. Eine unterbliebene Anhörung kann bis zur letzten Tatsacheninstanz des sozialgerichtlichen Verfahrens <b>nachgeholt</b> werden (§ 41 Abs. 1 Nr. 3, Abs. 2 SGB X).</p>
<div class="mark"><b>Praxis:</b> Das Anhörungsschreiben ist die erste und oft beste Gelegenheit, eine Rückforderung oder Leistungsminderung abzuwenden. Es sollte nie unbeantwortet bleiben.</div>`,
 f:'Anhörung ≠ Verwaltungsakt; Heilung bis zur letzten Tatsacheninstanz möglich.',rel:['n_va','n_pflv','n_aufheb','f1_1'],l:LK(['SGB X',24],['SGB X',41])});
N('n_va','t_verfahren','Verwaltungsakt: Begriff, Form, Wirksamkeit',{p:'§§ 31–42 SGB X',k:['SGB X|31','SGB X|33','SGB X|35','SGB X|36','SGB X|39','SGB X|40','SGB X|42'],m:[3],src:'SGBX',sum:'Regelung eines Einzelfalls mit Außenwirkung; auch ein falscher Bescheid wird wirksam und bestandskräftig, wenn er nicht rechtzeitig angefochten wird.',
 b:`<p><b>§ 31 Satz 1 SGB X:</b> Verwaltungsakt ist jede Verfügung, Entscheidung oder andere hoheitliche Maßnahme, die eine Behörde zur Regelung eines Einzelfalles auf dem Gebiet des öffentlichen Rechts trifft und die auf unmittelbare Rechtswirkung nach außen gerichtet ist. <b>Kein</b> Verwaltungsakt sind bloße Informationsschreiben, Terminerinnerungen ohne Rechtsfolgenbelehrung oder Anhörungsschreiben. Dauerverwaltungsakte (Bewilligung laufender Leistungen) sind für §§ 45, 48 SGB X wichtig (Einheit 9).</p>
<h4>Formelle Anforderungen – Prüffragen</h4>
<div class="tw"><table><thead><tr><th>Anforderung</th><th>Norm</th><th>Prüffrage</th></tr></thead><tbody>
<tr><td>Bestimmtheit</td><td>§ 33 Abs. 1 SGB X</td><td>Wer erhält/schuldet was, in welcher Höhe, für welchen Zeitraum?</td></tr>
<tr><td>Form</td><td>§ 33 Abs. 2, 3 SGB X</td><td>Schriftlich, elektronisch, mündlich; Behörde erkennbar</td></tr>
<tr><td>Begründung</td><td>§ 35 SGB X</td><td>Wesentliche tatsächliche und rechtliche Gründe; bei Ermessen: Gesichtspunkte der Ermessensausübung</td></tr>
<tr><td>Rechtsbehelfsbelehrung</td><td>§ 36 SGB X, § 66 SGG</td><td>Widerspruch, Stelle, Form, Frist? Fehlt sie oder ist falsch: Jahresfrist</td></tr>
<tr><td>Bekanntgabe</td><td>§ 37 SGB X</td><td>Wann und wem gegenüber?</td></tr></tbody></table></div>
<h4>Wirksamkeit, Nichtigkeit, Heilung</h4>
<p>Wirksam mit Bekanntgabe (§ 39 Abs. 1). Auch ein <b>rechtswidriger</b> Verwaltungsakt bleibt wirksam, bis er aufgehoben wird; nur ein <b>nichtiger</b> ist unwirksam (§ 39 Abs. 3, § 40). Verfahrens- und Formfehler können geheilt (§ 41) oder unbeachtlich (§ 42) sein.</p>
<div class="mark"><b>Wichtigster Merksatz der Einheit:</b> Ein falscher Bescheid wird bestandskräftig, wenn er nicht rechtzeitig angefochten wird.</div>`,
 f:'Formelle Prüfung eines Bescheids in fünf Punkten: Bestimmtheit, Form, Begründung, Rechtsbehelfsbelehrung, Bekanntgabe.',
 q:['Ist ein rechtswidriger Bescheid unwirksam?','Nein. Ein Verwaltungsakt wird mit Bekanntgabe wirksam und bleibt es, auch wenn er rechtswidrig ist, bis er aufgehoben wird; nur nichtige Verwaltungsakte sind unwirksam (§ 39 SGB X). Deshalb muss er rechtzeitig angefochten werden.'],
 rel:['n_bekanntgabe','n_wid','n_s35','f3_3'],l:LK(['SGB X',31],['SGB X',33],['SGB X',35],['SGB X',36],['SGB X',39]),});
N('n_s35','t_verfahren','Begründung und Rechtsbehelfsbelehrung',{p:'§§ 35, 36 SGB X',k:['SGB X|35','SGB X|36'],m:[3],src:'SGBX',sum:'Ein Bescheid muss seine wesentlichen Gründe nennen und über den Rechtsbehelf belehren.',
 b:`<p>Nach <b>§ 35 SGB X</b> sind die wesentlichen tatsächlichen und rechtlichen Gründe mitzuteilen; bei Ermessensentscheidungen auch die Gesichtspunkte der Ermessensausübung. <b>§ 36 SGB X</b> und <b>§ 66 SGG</b>: Die Rechtsbehelfsbelehrung muss Widerspruch, Stelle, Form und Frist nennen. Fehlt sie oder ist sie unrichtig, gilt die <b>Jahresfrist</b> (§ 66 Abs. 2 SGG). Siehe <a data-go="n_va">Verwaltungsakt</a> und <a data-go="n_wid">Widerspruch</a>.</p>`,
 f:'Fehlende Begründung ist ein Warnsignal (§ 31 SGB I); fehlende Belehrung verlängert die Frist auf ein Jahr.',rel:['n_va','n_s31','n_wid'],l:LK(['SGB X',35],['SGB X',36])});
N('n_bekanntgabe','t_verfahren','Bekanntgabe und Fristberechnung',{p:'§ 37 SGB X, § 64 SGG',k:['SGB X|37','SGG|64'],m:[3],src:'SGBX',sum:'Bescheid gilt am vierten Tag nach Aufgabe zur Post als bekannt gegeben; Fristen beginnen mit der Bekanntgabe, nicht mit dem Lesen.',
 b:`<p><b>§ 37 SGB X:</b> Ein Verwaltungsakt ist demjenigen bekannt zu geben, für den er bestimmt ist oder der von ihm betroffen wird; bei Bevollmächtigtem kann an diesen bekannt gegeben werden. Ein schriftlicher oder elektronisch übermittelter Verwaltungsakt gilt am <b>vierten Tag nach Aufgabe zur Post bzw. Absendung</b> als bekannt gegeben – nicht, wenn er nicht oder später zuging; <b>im Zweifel muss die Behörde den Zugang nachweisen</b>. Mit Einwilligung kann ein elektronischer Verwaltungsakt zum Abruf bereitgestellt werden (Abs. 2a): Bekanntgabe am vierten Tag nach Absendung der Benachrichtigung.</p>
<h4>Rechenbeispiel</h4>
<p>Bescheid am Donnerstag, 5. November 2026, zur Post → gilt am Montag, 9. November 2026 als bekannt gegeben → Widerspruchsfrist (ein Monat, § 84 Abs. 1 SGG) endet mit Ablauf des 9. Dezember 2026 (§ 64 SGG). Fällt das Fristende auf einen Samstag, Sonntag oder Feiertag, endet die Frist am nächsten Werktag (§ 64 Abs. 3 SGG).</p>
<h4>Bekanntgabe bei bestehender Betreuung</h4>
<p>Ist der betreute Mensch <b>geschäftsunfähig</b>, kann der Bescheid wirksam nur dem Betreuer bekannt gegeben werden. Ist er <b>handlungsfähig</b>, ist die Bekanntgabe an ihn selbst wirksam, auch wenn die Betreuung den Bereich umfasst – die Frist läuft dann ab dieser Bekanntgabe.</p>
<div class="mark"><b>Checkliste „Bescheid-Eingang“:</b> 1. Eingangsdatum vermerken, Umschlag aufbewahren. 2. Bekanntgabetag berechnen. 3. Fristende im Fristenkalender, Vorfrist eine Woche vorher. 4. Bescheid auf Bestimmtheit, Begründung, Berechnung, Belehrung prüfen. 5. Mit dem betreuten Menschen besprechen (§ 1821 BGB). 6. Im Zweifel fristwahrend Widerspruch einlegen, Begründung nachreichen.</div>`,
 f:'Rechenaufgaben zur Bekanntgabe (+3 Tage) und Fristende (Monat, Wochenende/Feiertag) sind prüfungsrelevant.',
 q:['Bescheid am Donnerstag, 5.11.2026, zur Post gegeben: Wann endet die Widerspruchsfrist?','Bekanntgabe am 9.11.2026 (vierter Tag); Fristende mit Ablauf des 9.12.2026 (§ 84 Abs. 1 SGG, § 64 SGG); bei Wochenende/Feiertag am nächsten Werktag.'],
 rel:['n_wid','n_handlung','n_va','f3_4'],l:LK(['SGB X',37],['SGG',64],['SGG',84])});
N('n_datenschutz','t_verfahren','Sozialdatenschutz',{p:'§ 35 SGB I, §§ 67 ff. SGB X',k:['SGB I|35'],m:[3],src:'SGBI',sum:'Sozialdaten dürfen nicht unbefugt verarbeitet werden; Weitergabe an Dritte braucht Rechtsgrundlage oder Einwilligung.',
 b:`<p><b>§ 35 Abs. 1 Satz 1 SGB I:</b> Jeder hat Anspruch darauf, dass seine Sozialdaten von den Leistungsträgern nicht unbefugt verarbeitet werden (Sozialgeheimnis).</p>
<ul><li>Der Betreuer erhält Auskunft über Sozialdaten als gesetzliche Vertretung im Rahmen des Aufgabenkreises.</li><li>Weitergabe an Dritte (Vermieter, Angehörige, Einrichtung) braucht Rechtsgrundlage oder Einwilligung; Entbindungen von der Schweigepflicht auf den konkreten Zweck beschränken.</li><li>Die Mitwirkungspflichten (§§ 60 ff. SGB I) gehen nicht weiter, als für die Leistung erforderlich (Einheit 9).</li></ul>`,
 f:'Entbindung von der Schweigepflicht zweckgebunden und eng formulieren.',rel:['n_mitw','n_grundsaetze'],l:LK(['SGB I',35])});

N('f3_1','t_faelle','Fall 3.1: Der Antrag im Briefkasten des Rathauses',{p:'Fall',m:[3],src:'SGBI',sum:'Formloser Antrag bei der Gemeinde, Weiterleitungspflicht und Rückwirkung.',
 b:`<h4>Sachverhalt</h4><p>Herr P., 58 Jahre, Dresden-Gorbitz, seit einem Schlaganfall im März halbseitig gelähmt, Betreuung für Vermögenssorge, Behördenangelegenheiten und Gesundheitssorge. Noch vor der Bestellung hat die Nachbarin am 28. April ein formloses Schreiben „Ich brauche Geld zum Leben, Herr P.“ in den Briefkasten des Ortsamts geworfen. Das Ortsamt hat es bis heute (3. Juni) nicht weitergegeben. Das Jobcenter sagt: „Leistungen gibt es erst ab Antragseingang bei uns, also ab Juni.“ Herr P. hat seit April kein Einkommen und kein Vermögen.</p>
<h4>Leitfragen</h4><ol><li>Wurde am 28. April ein Antrag gestellt?</li><li>Bedeutung des Eingangs bei der Gemeinde?</li><li>Was hätte das Ortsamt tun müssen, was kann die Betreuerin jetzt tun?</li></ol>
<details><summary>Lösungshinweise</summary><ol><li><b>Ja.</b> Der Antrag ist formfrei; erkennbar wird Geld zum Lebensunterhalt begehrt. Auslegung nach dem Meistbegünstigungsprinzip (SGB-II-Antrag). <a data-go="n_antrag">§ 16 SGB I</a>.</li><li>Gemeinden müssen Anträge entgegennehmen (§ 16 Abs. 1) und <b>unverzüglich weiterleiten</b> (Abs. 2); der Antrag gilt als am 28. April gestellt. Im SGB II wirkt der Antrag auf den Ersten des Antragsmonats zurück, hier den <b>1. April</b> (§ 37 Abs. 2 SGB II).</li><li>Das Ortsamt hätte sofort weiterleiten müssen. Jetzt: Weiterleitung verlangen, beim Jobcenter Leistungen ab 1. April beantragen und die Unterlagen (Eingangsnachweis, Zeugin Nachbarin) vorlegen; ggf. Herstellungsanspruch (<a data-go="n_herstellung">Pflichtverletzung</a>), Eilantrag bei akuter Notlage.</li></ol></details>`,
 rel:['n_antrag','n_herstellung','n_zugang'],l:[]});
N('f3_2','t_faelle','Fall 3.2: „Wir haben Ihnen doch eine Broschüre gegeben“',{p:'Fall',m:[3],src:'SGBI',sum:'Beratungspflicht, Herstellungsanspruch und Rentenantrag.',
 b:`<h4>Sachverhalt</h4><p>Frau L., 63 Jahre, bezieht Grundsicherungsgeld und ist seit Jahren schwerbehindert (GdB 60). 2025 wird ihr beim Jobcenter erklärt, sie müsse „bis zur Rente durchhalten“. Niemand weist sie auf eine mögliche Altersrente für schwerbehinderte Menschen und eine Rentenauskunft hin. Die Betreuerin erfährt dies erst jetzt.</p>
<details><summary>Lösungshinweise</summary><ol><li><b>Beratungspflicht:</b> Das Jobcenter hat keine allgemeine Pflicht zur Rentenberatung, muss aber auf naheliegende Gestaltungsmöglichkeiten hinweisen, zumal es nach § 12a SGB II vorrangige Leistungen einfordern kann. Rentenberatung selbst: Deutsche Rentenversicherung (§ 14 Satz 2 SGB I).</li><li><b>Herstellungsanspruch:</b> richtet sich gegen den Träger, dem die Pflichtverletzung zuzurechnen ist; Beratungsfehler eines anderen Trägers werden zugerechnet, wenn dieser arbeitsteilig eingebunden ist – im Einzelfall zu prüfen; Prüfungsschritte benennen, kein sicheres Ergebnis erwartet. <a data-go="n_herstellung">Voraussetzungen</a>.</li><li><b>Vorgehen:</b> sofort Rentenantrag stellen (§ 16 SGB I, § 115 SGB VI), Rentenbeginn nach § 99 SGB VI prüfen lassen, im Antrag auf fehlende Beratung hinweisen und hilfsweise den Herstellungsanspruch geltend machen; Folgen für den SGB-II-Bezug prüfen (§ 7 Abs. 4 SGB II: Ausschluss bei Altersrente, dann SGB XII).</li></ol></details>`,
 rel:['n_herstellung','n_beratung','n_rente','n_ausschl'],l:[]});
N('f3_3','t_faelle','Fall 3.3: Der unklare Bescheid',{p:'Fall',m:[3],src:'SGBX',sum:'Mängel eines Bescheids ohne Datum, Begründung und Belehrung.',
 b:`<h4>Sachverhalt</h4><p>Die Betreuerin von Herrn D. erhält die Kopie eines Schreibens der Familienkasse: „Für Ihr Kind wird das Kindergeld ab sofort nicht mehr gezahlt. Mit freundlichen Grüßen.“ Datum, Begründung und Rechtsbehelfsbelehrung fehlen.</p>
<details><summary>Lösungshinweise</summary><ol><li><b>Verwaltungsakt:</b> Regelung eines Einzelfalls mit Außenwirkung. Hinweis: Kindergeld nach dem EStG ist steuerrechtlich geregelt (Familienkassen, Einspruch nach AO, Finanzgerichte); Kinderzuschlag nach dem BKGG unterliegt dagegen dem SGB X und dem Sozialrechtsweg.</li><li><b>Mängel:</b> fehlende Bestimmtheit („ab sofort“), fehlende Begründung, fehlende Belehrung → Jahresfrist (§ 66 Abs. 2 SGG; im Steuerrecht entsprechend § 356 Abs. 2 AO). <a data-go="n_va">Prüfpunkte</a>.</li><li><b>Vorgehen:</b> Rechtsbehelf vorsorglich einlegen, Akteneinsicht und Begründung verlangen.</li></ol></details>`,
 rel:['n_va','n_wid'],l:[]});
N('f3_4','t_faelle','Fall 3.4: Bescheid an den betreuten Menschen',{p:'Fall',m:[3],src:'SGBX',sum:'Wirksame Bekanntgabe an die handlungsfähige betreute Person und abgelaufene Frist.',
 b:`<h4>Sachverhalt</h4><p>Frau S. ist geschäftsfähig, aber in Behördenangelegenheiten betreut. Das Sozialamt Dresden schickt einen Aufhebungsbescheid nur an Frau S.; sie legt ihn ungeöffnet in eine Schublade. Die Betreuerin findet ihn sechs Wochen nach Aufgabe zur Post.</p>
<details><summary>Lösungshinweise</summary><ol><li><b>Bekanntgabe:</b> Frau S. ist handlungsfähig (§ 11 Abs. 1 Nr. 1 SGB X), die Bekanntgabe an sie ist wirksam und gilt am vierten Tag nach Aufgabe zur Post; die Widerspruchsfrist ist abgelaufen. <a data-go="n_bekanntgabe">Fristberechnung</a>.</li><li><b>Rettung:</b> Wiedereinsetzung (§ 67 SGG) nur bei fehlendem Verschulden – eng, z. B. wenn Frau S. krankheitsbedingt die Bedeutung nicht erkennen konnte; unabhängig davon <b>Überprüfungsantrag nach § 44 SGB X</b> (Einheit 9).</li><li><b>Prävention:</b> Träger bitten, Schreiben auch an die Betreuerin zu richten; mit Frau S. Weitergabe der Behördenpost vereinbaren.</li></ol></details>`,
 rel:['n_bekanntgabe','n_handlung','n_ueberpr','n_wieder'],l:[]});
